INSERT INTO animal (name, type, gender, age, breed, sterilized, vaccinated, health, location, status, cover, images, story, tags, source, created_at) VALUES
('小橘', 'cat', 'male', '1 岁', '中华田园猫', 1, 1, '健康，已完成驱虫', '东城区 · 幸福里小区', 'available', '', JSON_ARRAY(), '在小区车棚被发现时只有巴掌大，被救助人带回家养了一个月，现在亲人不怕生，会主动蹭手。', JSON_ARRAY('亲人', '已绝育', '会用猫砂'), 'official', NOW() - INTERVAL 1 DAY),
('煤球', 'cat', 'female', '2 岁', '玳瑁猫', 1, 1, '健康', '西城区 · 救助站', 'available', '', JSON_ARRAY(), '性格安静，喜欢趴在窗台晒太阳。前主人搬家无法带走，送到救助站后一直等待新家。', JSON_ARRAY('安静', '已绝育'), 'official', NOW() - INTERVAL 2 DAY),
('阿黄', 'dog', 'male', '3 岁', '中华田园犬', 1, 1, '健康，轻微牙结石', '朝阳区 · 救助站', 'available', '', JSON_ARRAY(), '在工地附近流浪了半年，性格温顺，会坐下和握手，牵绳走路很稳。', JSON_ARRAY('温顺', '会握手', '已绝育'), 'official', NOW() - INTERVAL 3 DAY),
('豆豆', 'dog', 'female', '1 岁', '柯基串', 0, 1, '健康', '海淀区 · 临时寄养家庭', 'available', '', JSON_ARRAY(), '精力旺盛，喜欢玩球，适合有院子或每天能遛狗的家庭。', JSON_ARRAY('活泼', '亲人'), 'official', NOW() - INTERVAL 4 DAY),
('大花', 'cat', 'female', '4 岁', '三花猫', 1, 1, '健康', '东城区 · 幸福里小区', 'adopted', '', JSON_ARRAY(), '已经被一位独居老人领养，生活稳定。', JSON_ARRAY('已领养'), 'official', NOW() - INTERVAL 5 DAY),
('黑豹', 'dog', 'male', '2 岁', '拉布拉多串', 1, 1, '健康', '丰台区 · 救助站', 'pending', '', JSON_ARRAY(), '性格稳重，正在审核一位申请人的领养资格。', JSON_ARRAY('稳重'), 'official', NOW() - INTERVAL 6 DAY),
('奶糖', 'cat', 'female', '6 个月', '白猫', 0, 1, '健康，待绝育', '西城区 · 救助站', 'available', '', JSON_ARRAY(), '同窝三只里最瘦小的一只，现在已经能吃能玩，等待一个耐心的家。', JSON_ARRAY('幼猫', '亲人'), 'official', NOW() - INTERVAL 7 DAY),
('旺财', 'dog', 'male', '5 岁', '柴犬串', 1, 1, '健康', '通州区 · 救助站', 'available', '', JSON_ARRAY(), '被遗弃在公园门口，等了两周没有主人认领。性格独立但不咬人。', JSON_ARRAY('独立', '已绝育'), 'official', NOW() - INTERVAL 8 DAY);
INSERT INTO notice (title, content, published_at) VALUES
('暖爪 WarmPaws 试运行公告', '暖爪 WarmPaws 小程序开始试运行。\n\n当前提供流浪动物档案浏览、领养申请提交与进度查询三项服务。\n\n试运行期间，动物信息由合作救助站与管理员录入，如发现信息有误，请通过意见反馈告诉我们。', NOW() - INTERVAL 1 DAY),
('领养流程与回访说明', '领养流程：提交申请 → 平台审核 → 工作人员联系 → 线下见面 → 交接 → 回访。\n\n审核一般在 3 个工作日内完成，结果可在「我的 - 我的申请」中查看。\n\n平台不收取任何领养费用。', NOW() - INTERVAL 3 DAY),
('合作救助站招募说明', '我们正在招募合作救助站，为流浪动物提供档案录入与领养对接支持。\n\n合作不涉及资金往来，平台仅提供信息展示与申请管理工具。\n\n有意向的救助组织可通过意见反馈留下联系方式。', NOW() - INTERVAL 5 DAY);
INSERT INTO agreement (type, title, content) VALUES
('agreement', '用户协议', '暖爪 WarmPaws 用户协议\n\n一、服务说明\n本小程序提供流浪动物档案展示、领养申请提交与进度查询服务。平台不从事动物买卖，不收取任何领养费用。\n\n二、账号说明\n本小程序使用微信账号登录，无需注册。你的账号与微信 openid 绑定，注销后重新进入将创建新账号。\n\n三、用户行为\n你承诺提交的领养申请与动物投稿信息真实有效，不得冒用他人身份，不得利用平台从事任何违法活动。\n\n四、免责声明\n动物信息由救助组织、管理员或用户投稿录入，平台尽力核实但不保证完全准确。领养交接由申请人与救助方线下完成。'),
('privacy', '隐私政策', '暖爪 WarmPaws 隐私政策\n\n一、我们收集的信息\n1. 微信登录标识（openid），用于识别账号；\n2. 你主动填写的昵称；\n3. 你提交领养申请时填写的姓名、联系方式、居住情况与养宠经验；\n4. 你提交动物投稿时填写的信息、照片与联系方式。\n\n二、信息的使用\n仅用于领养审核、联系与回访，以及动物投稿审核，不用于任何营销用途，不向无关第三方提供。\n\n三、头像说明\n头像由你主动选择，仅保存在本机，不上传服务器。\n\n四、注销与保留\n注销后，账号、收藏、意见反馈将被删除；已审核的领养申请记录及其中填写的姓名、联系方式会保留，用于领养回访，保留期限为审核结束后 12 个月。待审核的申请在注销时直接删除。\n\n五、你的权利\n你可以随时修改昵称、撤销待审核的申请或投稿，或注销账号。'),
('adopt-rule', '领养须知', '领养须知\n\n一、基本条件\n1. 年满 18 周岁，有稳定住所和收入；\n2. 家庭成员同意领养，租房需房东允许养宠；\n3. 承诺科学喂养、定期免疫、适龄绝育，不散养、不虐待、不遗弃。\n\n二、领养流程\n提交申请 → 平台审核 → 工作人员联系沟通 → 线下见面交接 → 定期回访。\n\n三、回访要求\n领养后 1 个月内接受一次回访，之后按约定接受不定期回访，需配合提供动物近况。\n\n四、费用说明\n平台不收取领养费用。疫苗、绝育等已产生费用由救助方与领养人线下协商。\n\n五、撤回与退回\n审核通过前可随时撤销申请；领养后若确实无法继续饲养，应联系平台退回，不得自行转送或遗弃。');
